export function translate(source, language, parameters = {}) {
  const key = source.replace(/\s+/g, " ").trim();
  const template = language === "en" ? (english[key] ?? key) : key;
  return template.replace(
    /\{(\w+)\}/g,
    (match, name) => parameters[name] ?? match,
  );
}
